    chapters = {
        {
            chapter = "Hammertoe's Warning",
            faction = "Alliance",
            requiredLevel = 35,
            summary = "There's a crumpled map lying at Hammertoe's Digsite in the Badlands, and the note on it says Hammertoe Grez is alive. Prospector Ryedol, camped just down the road, will want to hear that.",
            recap = "It started with a crumpled map in the Badlands and a note on it saying Hammertoe Grez was alive. Hammertoe was, too, down in Uldaman, and missing an amulet. I got it back.\n\nThen the amulet went on tour: to a prospector in the Badlands, to a historian in Ironforge, to an advisor by way of a note, and back to the historian again. Every leg of it, I should say, walked by me.\n\nAt the end of all that walking, somebody finally handed me a proper job. Kill Ambassador Infernus in Angor Fortress, bring back proof, then go down into Uldaman again for the Tablet of Will before the Shadowforge got to it.\n\nCourier, soldier, treasure hunter. I'd never been all three on one errand before.",
            quests = {
                { id = 720, name = "A Sign of Hope", npc = "Crumpled Map" },
                { id = 721, name = "A Sign of Hope", npc = "Prospector Ryedol" },
                { id = 722, name = "Amulet of Secrets", npc = "Hammertoe Grez" },
                { id = 723, name = "Prospect of Faith", npc = "Hammertoe Grez" },
                { id = 724, name = "Prospect of Faith", npc = "Prospector Ryedol" },
                { id = 725, name = "Passing Word of a Threat", npc = "Historian Karnik" },
                { id = 726, name = "Passing Word of a Threat", npc = "Advisor Belgrum" },
                { id = 762, name = "An Ambassador of Evil", npc = "Historian Karnik" },
                { id = 1139, name = "The Lost Tablets of Will", npc = "Advisor Belgrum" },
                { id = 704, name = "Agmond's Fate", npc = "Prospector Ironband", optional = true, recap = "Prospector Ironband in Loch Modan had lost a prospector named Agmond, whose last report mentioned carved stone urns at the dig outside Uldaman, and Ironband suspected the urns were what had stirred up the troggs. I brought back four. The troggs did seem to feel strongly about them." },
                { id = 1360, name = "Reclaimed Treasures", npc = "Krom Stoutarm", optional = true, recap = "When the troggs overran Uldaman, Krom Stoutarm left his greatest treasure behind in a chest at the end of the North Common Hall. I fought my way to it and carried it home to Ironforge, and it was a beer stein. A Stoutarm without a stein, Krom explained with feeling, is hardly a Stoutarm at all." },
                { id = 2398, name = "The Lost Dwarves", npc = "Prospector Stormpike", optional = true },
                { id = 2240, name = "The Hidden Chamber", npc = "Baelog", optional = true, recap = "Prospector Stormpike of the Explorers' League sent me after Baelog, whose band had gone into Uldaman and got stuck there. Baelog couldn't go anywhere, but his journal told me how to open a hidden chamber behind a huge locked door, and the chamber was real. Stormpike admitted to having had doubts, which Baelog never had." },
            },
        },
        {
            chapter = "The Shattered Necklace",
            follows = false,
            requiredLevel = 37,
            summaryAlliance = "Somewhere in Uldaman, a shattered necklace is waiting to be found. Broken, but fine work. Track down whoever made it and you might learn what it's worth.",
            summaryHorde = "Dran Droffers, of Droffers and Son Salvage in Orgrimmar, has heard about a valuable necklace somewhere in the Uldaman dig site. Possibly damaged. Droffers doesn't mind damaged, as long as somebody brings it back.",
            recapAlliance = "Somewhere in Uldaman I picked up a shattered necklace. Fine work, badly broken. A thing like that has a maker, so I went looking and found him in Ironforge: Talvash del Kissel. He'd tell me all about it, for five silver bars.\n\nI paid a man to tell me about his own necklace. Moving on.\n\nHis story sent me back into Uldaman, to what was left of a paladin and a journal saying where the gems had gone. Three gems, three corners of the dig, one of them in the fist of the trogg leader, who didn't let go easily. Talvash had given me a Phial of Scrying, so I could report from down there without the walk.\n\nLast, he wanted a power source off the strongest construct in the place. That was Archaedas. Talvash got his necklace back together. I got a story.",
            recapHorde = "Dran Droffers runs a salvage business in Orgrimmar, Droffers and Son, and had heard about a valuable necklace somewhere in the Uldaman dig site. Probably damaged. Droffers didn't mind damaged.\n\nI found it, and it was. No gems. Down in the depths I found what was left of a paladin, and a journal that said where the gems had gone, and I couldn't read a word of it. The nearest translator was Jarkal Mossmeld in Kargath, who'd do it in exchange for borrowing the necklace. Everybody wants a little something.\n\nThree gems and a power source later, the last of them pried off the strongest construct in Uldaman, I'd worn a groove in the road between Kargath and Orgrimmar, and Droffers had the necklace and the gem salvage.\n\nIn that trade, everything's salvage eventually.",
            quests = {
                { id = 2198, name = "The Shattered Necklace", npc = "Shattered Necklace", faction = "Alliance", mapID = 230, x = 0.3900, y = 0.3000, location = "Uldaman" },
                { id = 2199, name = "Lore for a Price", npc = "Talvash del Kissel", faction = "Alliance" },
                { id = 2200, name = "Back to Uldaman", npc = "Talvash del Kissel", faction = "Alliance" },
                { id = 2201, name = "Find the Gems", npc = "Remains of a Paladin", faction = "Alliance" },
                { id = 2204, name = "Restoring the Necklace", npc = "Talvash del Kissel", faction = "Alliance" },
                { id = 2283, name = "Necklace Recovery", npc = "Dran Droffers", faction = "Horde" },
                { id = 2284, name = "Necklace Recovery, Take 2", npc = "Dran Droffers", faction = "Horde" },
                { id = 2318, name = "Translating the Journal", npc = "Remains of a Paladin", faction = "Horde" },
                { id = 2338, name = "Translating the Journal", npc = "Jarkal Mossmeld", faction = "Horde" },
                { id = 2339, name = "Find the Gems and Power Source", npc = "Jarkal Mossmeld", faction = "Horde" },
                { id = 2340, name = "Deliver the Gems", npc = "Jarkal Mossmeld", faction = "Horde" },
                { id = 2341, name = "Necklace Recovery, Take 3", npc = "Dran Droffers", faction = "Horde" },
                { id = 2361, name = "Restoring the Necklace", npc = "Talvash del Kissel", faction = "Alliance", optional = true, recap = "In the end Talvash del Kissel let me keep the necklace, on two conditions: that I tell everyone, loudly and often, who made it, and that I mention it really isn't cursed. Talvash made it, and it isn't cursed, as far as I know." },
                { id = 17, name = "Uldaman Reagent Run", npc = "Ghak Healtouch", faction = "Alliance", optional = true, recap = "Ghak Healtouch, the alchemist in Thelsamar, wanted a dozen magenta fungus caps from the Uldaman tunnels, with a warning that they puff poison spores when jostled. They do. Ghak paid me with a restorative potion and called the caps an interesting study, yon verily, and I still don't know what yon verily means." },
                { id = 2202, name = "Uldaman Reagent Run", npc = "Jarkal Mossmeld", faction = "Horde", optional = true, recap = "Jarkal Mossmeld in Kargath wanted a dozen magenta fungus caps out of the Uldaman tunnels, which let off poison spores if you disturb them, so a little care was called for. I took a little care and a lot of poison. Jarkal paid me with a restorative potion, which was exactly the right reward." },
                { id = 2342, name = "Reclaimed Treasures", npc = "Patrick Garrett", faction = "Horde", optional = true, recap = "Patrick Garrett swept the bat pens in the Undercity and felt it was beneath a Garrett. The family weapon was still in their old chest in Uldaman's South Common Hall, from back when the Garretts dug there. I brought it back, and Patrick turned straight to the bats and told them to tremble, which they didn't." },
                { id = 709, name = "Solution to Doom", npc = "Theldurin the Lost", optional = true, recap = "Theldurin the Lost, a jumpy dwarf out in the Badlands, was sure a doom was coming and wouldn't say its name in case it heard him. He needed the Tablet of Ryun'eh, from a chest in Uldaman older than anything dwarves ever made. I brought it, and he said it might hold the secret to saving us all, though he still wouldn't say from what." },
                { id = 2418, name = "Power Stones", npc = "Rigglefuzz", optional = true, recap = "Rigglefuzz, a tinkerer in the Badlands, had once shown the Shadowforge dwarves how to use the power stones they dig out of Uldaman, and was thanked by being thrown out. Now Rigglefuzz wanted sixteen of them, to run a robotic rodent forever. The Shadowforge were no better at sharing the second time." },
            },
        },
        {
            chapter = "The Platinum Discs",
            follows = false,
            requiredLevel = 40,
            summary = "At the very bottom of Uldaman, behind the last of its guardians, a stone watcher keeps the Discs of Norgannon. It has been waiting a very long time for someone to come and ask it questions.",
            recapAlliance = "Past Archaedas, at the very bottom of Uldaman, sits a stone watcher that has been waiting a very long time for someone to ask it a question. I asked. It answered at length. Then I woke the Discs of Norgannon, and they answered at greater length.\n\nThe short of it: the titans shaped the world, and they made the earthen out of stone to look after it. Over the ages the earthen went soft and became something else. You've met the result. They run Ironforge.\n\nI came away with a miniature copy of the discs and took it to the Explorers' League in Ironforge. Proof of where the dwarves came from, small enough to carry under one arm.\n\nMy reward was a voucher for Dinita Stonemantle in the Vault. I found out where a whole people came from and got paid by the bank.",
            recapHorde = "Behind Archaedas, at the bottom of Uldaman, a stone watcher sits waiting for someone with questions. I had a few. It had very old answers, and when it ran out, I woke the Discs of Norgannon for the rest.\n\nHere's the gist. The titans shaped the world and made the earthen out of stone to tend it, and over the ages the earthen softened into flesh. Into dwarves, as it happens. All those dwarves digging up the Badlands were digging up their own family history and didn't know it.\n\nI came away with a miniature copy of the discs and took it to Thunder Bluff, to Sage Truthseeker, who understood exactly what it was.\n\nThen I was handed a voucher for Bena Winterhoof. Secrets of creation, paid out in a slip of paper. I took it. Paper spends.",
            quests = {
                { id = 2278, name = "The Platinum Discs", npc = "The Discs of Norgannon" },
                { id = 2279, name = "The Platinum Discs", npc = "The Discs of Norgannon", faction = "Alliance" },
                { id = 2439, name = "The Platinum Discs", npc = "High Explorer Magellas", faction = "Alliance" },
                { id = 2280, name = "The Platinum Discs", npc = "The Discs of Norgannon", faction = "Horde" },
                { id = 2440, name = "The Platinum Discs", npc = "Sage Truthseeker", faction = "Horde" },
